{
	int v_div, i_div, rangeV, rangeI, i;
	long val1, val1_max, val1_0, val1_min, val2, val2_max, val2_0, val2_min;

	v_div = (int)myCh->misc.cmd_v_div;
	i_div = (int)myCh->misc.cmd_i_div;
	rangeV = myCh->op.rangeV;
	rangeI = myCh->op.rangeI;

	if(myCh->misc.cmd_i[0] >= 0) {
		val1 = myCh->misc.cmd_v[0];
	} else {
		val1 = myCh->misc.cmd_v[1];
	}
	val1_max = myPs->config.maxV[rangeV];
	val1_0 = 0;
	val1_min = val1_max * (-1);

	val2 = myCh->misc.cmd_i[0];
	val2_max = myPs->config.maxI[rangeI];
	val2_0 = 0;
	val2_min = myPs->config.minI[rangeI];

	switch(myCh->signal[C_SIG_SEMI_SWITCH]) {
		case P0:
			if(slot != 0) break;
			cCalCmdI(ch, val2_0, 1, rangeI);
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P1:
			if(slot != 0) break;
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P2:
			if(slot != 0) break;
			cOutSwitch_Select_OFF_1(ch, rangeV, rangeI);
			myCh->signal[C_SIG_SEMI_SWITCH] = P11;
			break;
		default:
			if(slot != 0) break;
			i = myCh->signal[C_SIG_SEMI_SWITCH] - P10;
			i *= (int)myPs->config.scan_period;
			if(i >= 200) {
				//200ms wait for Relay Active
				myCh->misc.semiSwitchState = SEMI_IDLE;
				myCh->signal[C_SIG_SELECTED_RANGE_I] = P0;
				myCh->signal[C_SIG_OUT_SWITCH] = P2;
				myCh->signal[C_SIG_SEMI_SWITCH] = P0;
				cCalCmdV(ch, val1_min, 1, rangeV);
				cCalCmdI(ch, val2_max, 1, rangeI);
			} else {
				myCh->signal[C_SIG_SEMI_SWITCH]++;
			}
			break;
	}
}

void cOutSwitch_P11_General1(int ch, int slot)
{
	int v_div, i_div, rangeV, rangeI;
	long val1, val1_max, val1_0, val1_min, val2, val2_max, val2_0, val2_min;

	v_div = (int)myCh->misc.cmd_v_div;
	i_div = (int)myCh->misc.cmd_i_div;
	rangeV = myCh->op.rangeV;
	rangeI = myCh->op.rangeI;

	if(myCh->misc.cmd_i[0] >= 0) {
		val1 = myCh->misc.cmd_v[0];
	} else {
		val1 = myCh->misc.cmd_v[1];
	}
	val1_max = myPs->config.maxV[rangeV];
	val1_0 = 0;
	val1_min = val1_max * (-1);

	val2 = myCh->misc.cmd_i[0];
	val2_max = myPs->config.maxI[rangeI];
	val2_0 = 0;
	val2_min = myPs->config.minI[rangeI];

	switch(myCh->signal[C_SIG_SEMI_SWITCH]) {
		case P0:
			if(slot != 0) break;
			switch(myData->AppControl.config.systemModel) {
				case C_VK_100V_200A_20A:
				case C_EIG_100V_200A_20A_2:
					cCalCmdV(ch, val1_min, 1, rangeV);
					cCalCmdI(ch, val2_0, 1, rangeI);
					myCh->signal[C_SIG_OUT_SWITCH] = P12;
					myCh->signal[C_SIG_SEMI_SWITCH] = P0;
					break;
				default:
					myCh->signal[C_SIG_OUT_SWITCH] = P12;
					myCh->signal[C_SIG_SEMI_SWITCH] = P0;
					break;
			}
			break;
		case P1:
			if(slot != 0) break;
			cCalCmdV(ch, val1_0, 1, rangeV);
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P2:
			if(slot != 0) break;
			cCalCmdV(ch, val1_min, 1, rangeV);
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P3:
			if(slot != 0) break;
			cCalCmdI(ch, val2_max, 1, rangeI);
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P4:
			if(slot != 0) break;
			myCh->signal[C_SIG_OUT_SWITCH] = P12;
			myCh->signal[C_SIG_SEMI_SWITCH] = P0;
			break;
	}
}

void cOutSwitch_P21_General1(int ch, int slot)
{
	int v_div, i_div, rangeV, rangeI;
	long val1, val1_max, val1_0, val1_min, val2, val2_max, val2_0, val2_min;

	v_div = (int)myCh->misc.cmd_v_div;
	i_div = (int)myCh->misc.cmd_i_div;
	rangeV = myCh->op.rangeV;
	rangeI = myCh->op.rangeI;

	if(myCh->misc.cmd_i[0] >= 0) {
		val1 = myCh->misc.cmd_v[0];
	} else {
		val1 = myCh->misc.cmd_v[1];
	}
	val1_max = myPs->config.maxV[rangeV];
	val1_0 = 0;
	val1_min = val1_max * (-1);

	val2 = myCh->misc.cmd_i[0];
	val2_max = myPs->config.maxI[rangeI];
	val2_0 = 0;
	val2_min = myPs->config.minI[rangeI];

	switch(myCh->signal[C_SIG_SEMI_SWITCH]) {
		case P0:
			if(slot != 0) break;
			if(myCh->misc.semiSwitchState == SEMI_I_P) {
				cCalCmdI(ch, val1_min, 1, rangeI);
				cCalCmdI(ch, val2_0, 1, rangeI);
			} else if(myCh->misc.semiSwitchState == SEMI_I_N) {
				cCalCmdI(ch, val1_max, 1, rangeI);
				cCalCmdI(ch, val2_0, 1, rangeI);
			} else {
				cCalCmdI(ch, val2_0, 1, rangeI);
			}
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P1:
			if(slot != 0) break;
			if(myCh->misc.semiSwitchState == SEMI_I_P) {
				cCalCmdI(ch, val1_min, 1, rangeI);
				cCalCmdI(ch, val2_0, 1, rangeI);
			} else if(myCh->misc.semiSwitchState == SEMI_I_N) {
				cCalCmdI(ch, val1_max, 1, rangeI);
				cCalCmdI(ch, val2_0, 1, rangeI);
			} else {
				cCalCmdV(ch, val1_0, 1, rangeV);
			}
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P2:
			if(slot != 0) break;
			if(myCh->misc.semiSwitchState == SEMI_I_P) {
				cCalCmdI(ch, val1_min, 1, rangeI);
				cCalCmdI(ch, val2_0, 1, rangeI);
			} else if(myCh->misc.semiSwitchState == SEMI_I_N) {
				cCalCmdI(ch, val1_min, 1, rangeI);
				cCalCmdI(ch, val2_0, 1, rangeI);
			} else {
				cCalCmdV(ch, val1_min, 1, rangeV);
			}
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		case P3:
			if(slot != 0) break;
			if(myCh->misc.semiSwitchState == SEMI_I_P) {
				cCalCmdV(ch, val1_min, 1, rangeV);
				cCalCmdI(ch, val2_max, 1, rangeI);
			} else if(myCh->misc.semiSwitchState == SEMI_I_N) {
				cCalCmdV(ch, val1_min, 1, rangeV);
				cCalCmdI(ch, val2_max, 1, rangeI);
			} else {
				cCalCmdI(ch, val2_max, 1, rangeI);
			}
			myCh->signal[C_SIG_OUT_SWITCH] = P22;
			myCh->signal[C_SIG_SEMI_SWITCH] = P0;
			break;
	}
}

void cOutSwitch_P51_General1(int ch, int slot)
{
	int v_div, i_div, rangeV, rangeI, i;
	long val1, val1_max, val1_0, val1_min, val2, val2_max, val2_0, val2_min;

	v_div = (int)myCh->misc.cmd_v_div;
	i_div = (int)myCh->misc.cmd_i_div;
	rangeV = myCh->op.rangeV;
	rangeI = myCh->op.rangeI;

	if(myCh->misc.cmd_i[0] >= 0) {
		val1 = myCh->misc.cmd_v[0];
	} else {
		val1 = myCh->misc.cmd_v[1];
	}
	val1_max = myPs->config.maxV[rangeV];
	val1_0 = 0;
	val1_min = val1_max * (-1);

	val2 = myCh->misc.cmd_i[0];
	val2_max = myPs->config.maxI[rangeI];
	val2_0 = 0;
	val2_min = myPs->config.minI[rangeI];

	switch(myCh->signal[C_SIG_SEMI_SWITCH]) {
		case P0:
			if(slot != 0) break;
			if(val2 >= 0) {
				cCalCmdV(ch, val1_max, 1, rangeV);
				cCalCmdI(ch, val2_min, 1, rangeI);
			} else {
				cCalCmdV(ch, val1_min, 1, rangeV);
				cCalCmdI(ch, val2_max, 1, rangeI);
			}
			myCh->signal[C_SIG_SEMI_SWITCH] = P10;
			break;
		case P10:
			if(slot != 0) break;
			if(myCh->op.state == C_CALI) {
				cOutSwitch_Select_ON_1(ch, rangeV, rangeI);
			} else if(myData->ChAttribute[ch].chNo_master != 0) { //for master
				if(val2 == 0) cOutSwitch_Select_OFF_1(ch, rangeV, rangeI);
				else cOutSwitch_Select_ON_1(ch, rangeV, rangeI);
			}
			myCh->signal[C_SIG_SEMI_SWITCH]++;
			break;
		default:
			if(slot != 0) break;
			i = myCh->signal[C_SIG_SEMI_SWITCH] - P10;
			i *= (int)myPs->config.scan_period;
			if(i >= 200) {
				//200ms wait for Relay Active
				cCalCmdV(ch, val1, v_div, rangeV);
				cCalCmdI(ch, val2, i_div, rangeI);
				myCh->signal[C_SIG_SELECTED_RANGE_I] = rangeI+1;
				myCh->signal[C_SIG_OUT_SWITCH] = P52;
				myCh->signal[C_SIG_SEMI_SWITCH] = P0;
			} else {
				myCh->signal[C_SIG_SEMI_SWITCH]++;
			}
			break;
	}
}

