int cFindADCaliPoint(int ch, double value, int type, int range, int state)
{
	int point, point1, rtn;
	int minus_v;	//jhkw_180124
	
	//jhkw_180124s
	switch(myData->AppControl.config.systemModel){
		case C_SKI_20V_300A_200A_100A_12KW:		//shh_231204
		case C_SKI_20V_300A_200A_100A_12KW_2:	//shh_231204
		case C_SKI_30V_600A_400A_200A_100A_36KW://ksh_250418
		case C_SKI_50V_500A_250A_25KW:	//ktg_190715
		case C_SKI_50V_500A_400A_200A_100A_100KW:
		case C_SKI_50V_500A_400A_200A_100A_100KW_2:
		case C_SKI_50V_1000A_500A_300A_100KW:	//ktg_190530
		case C_SKI_50V_1000A_500A_300A_100KW_2:	//ktg_190530
		case C_SKI_50V_1000A_500A_300A_100KW_3:	//ktg_190530
		case C_SKI_50V_1000A_500A_300A_100KW_4:	//ktg_190711
		case C_NORTHVOLT_400V_200A_100A_160KW:	//jhkw_200526
		case C_KTL_600V_200A_100A_20A_400KW:	//jhk_180731
			minus_v = 1;
			break;
		default:
			minus_v = 0;
	}
	//jhkw_180124e

	if(state == 0) {
		if(myData->cali[ch].mode == CALI_MODE_ONLY_CHECK) {
			point1 = myData->cali[ch].data[type][range].point.setPointNum;
			for(point=0; point < point1; point++) {
				if(myData->cali[ch].data[type][range].set_ad[point]
					>= value) {
					if(point == 0) return point;
					else return point-1;
				}
			}
			rtn = point1 - 2;
			if(rtn < 0) rtn = 0;
			return rtn;
		} else {
			//jhkw_180124s
			if(minus_v == 1) {
				if(value < 0 && type == 0) {
					value = value * (-1);
				}
			} else {
			}
			//jhkw_180124e
			point1 = myData->cali[ch].tmpCond[type][range].point.setPointNum;
			for(point=0; point < point1; point++) {
				if(myData->cali[ch].tmpData[type][range].set_ad[point]
					>= value) {
					if(point == 0) return point;
					else return point-1;
				}
			}
			rtn = point1 - 2;
			if(rtn < 0) rtn = 0;
			return rtn;
		}
	} else {
		//jhkw_180124s
		if(minus_v == 1) {
			if(value < 0 && type == 0) {
				value = value * (-1);
			}
		} else {
		}
		//jhkw_180124e
		point1 = myData->cali[ch].data[type][range].point.setPointNum;
		for(point=0; point < point1; point++) {
			if(myData->cali[ch].data[type][range].set_ad[point]
				>= value) {
				if(point == 0) return point;
				else return point-1;
			}
		}
		rtn = point1 - 2;
		if(rtn < 0) rtn = 0;
		return rtn;
	}
}

